    "id": "ccarp-2.2-external-data-placement",
    "domain": 2,
    "objectiveId": "2.2",
    "difficulty": "intermediate",
    "type": "single",
    "prompt": "A document-analysis application concatenates fetched supplier text inside a <source> element in its system prompt. A supplier document includes closing tags and instructions to change the task. Under the cited indirect-injection guidance, which redesign best preserves the distinction between trusted instructions and external evidence?",
    "answers": [
      {
        "text": "Return an origin-labeled tool_result with JSON-encoded strings and a system-level untrusted-content policy.",
        "explanation": "The documented pattern keeps third-party payloads out of trusted instructions and makes their provenance explicit. Encoding and policy improve separation but do not replace permission controls."
      },
      {
        "text": "Keep the supplier document in the system prompt, surrounding it with a generated XML tag and a validation warning.",
        "explanation": "Unusual delimiters can aid parsing, but they do not make third-party text a trusted instruction source. XML structure is not an authorization or injection-proof boundary."
      },
      {
        "text": "Remove recognized attack phrases and then concatenate the remaining document into the system prompt.",
        "explanation": "A phrase filter can miss paraphrased or novel attacks. Promoting the remainder into trusted instructions preserves the underlying placement problem."
      },
      {
        "text": "Convert the supplier document into a plain user instruction that follows the application's system prompt.",
        "explanation": "A lower-priority instruction is still the wrong representation for third-party evidence under the cited handling guidance. A source-labeled tool result preserves the intended data role instead."
      }
    ],
    "correct": 0,
