    "id": "ccarp-2.2-layered-prompt-guardrails",
    "domain": 2,
    "objectiveId": "2.2",
    "difficulty": "advanced",
    "type": "multiple",
    "prompt": "A research assistant already receives source-labeled tool results and a system policy that rejects instructions inside retrieved documents. It can read internal reports, and malicious search content asks it to upload them to an external URL. Which additional measures appropriately complement the prompt policy? Select 3 answers.",
    "answers": [
      {
        "text": "Restrict tool credentials, reachable destinations, and file access to what the authorized task requires.",
        "explanation": "Least privilege limits the consequences of a successful injection. These application and sandbox controls enforce boundaries outside the model's interpretation of prompt text."
      },
      {
        "text": "Screen returned content for redirection attempts and handle suspicious results without automatically passing them through for action.",
        "explanation": "Tool-output screening can identify attacks before the acting model consumes them. It is a complementary detection layer, not proof that all accepted content is safe."
      },
      {
        "text": "Allow a safe verdict from the content classifier to grant new upload destinations requested by that content.",
        "explanation": "A safety verdict does not authorize an external destination. Letting source content expand permissions creates an authorization bypass even when a classifier reports no attack."
      },
      {
        "text": "Test adversarial documents and tool outputs against the complete workflow, including attempted unauthorized uploads.",
        "explanation": "Adversarial tests check whether the prompt, screening, and action controls work together. Testing only benign summaries would miss the specified exfiltration failure path."
      }
    ],
