    "id": "ccarp-4.2-protect-heldout-incident-families",
    "domain": 4,
    "objectiveId": "4.2",
    "difficulty": "intermediate",
    "type": "single",
    "prompt": "A team builds a final evaluation set from incident reports. Many reports describe the same underlying incident using paraphrases, and some appear in the assistant's few-shot examples. A random row split gives excellent results. What change best tests generalization to unseen incidents?",
    "answers": [
      {
        "text": "Enlarge the random holdout while retaining the current few-shot examples.",
        "explanation": "More rows do not remove related incidents or prompt examples from the holdout. The evaluation can remain contaminated by material available during development."
      },
      {
        "text": "Remove exact text duplicates after the random split and keep all paraphrases.",
        "explanation": "Exact deduplication misses reports with different wording but the same incident and solution. Those related cases can still cross the development and evaluation boundary."
      },
      {
        "text": "Tune the few-shot examples on holdout errors, then reuse the holdout for final scoring.",
        "explanation": "Using holdout errors to improve the prompt turns that set into development data. Its later score no longer provides a protected final comparison."
      },
      {
        "text": "Isolate whole incident families from development data and prompt examples, then lock the holdout.",
        "explanation": "Group-wise separation prevents paraphrases of an incident from crossing into the final evaluation from any development source. Protecting that holdout also prevents prompt tuning on its errors; no universal split ratio is implied."
      }
    ],
    "correct": 3,
